    n = len(nums)

    # Edge case: cannot split a single element
    if n == 1:
        return False

    # Dictionary to store achievable sums for different sizes
    achievable_sums = defaultdict(set)
    achievable_sums[0].add(0)  # Base case: sum of 0 with size 0

    for num in nums:
        # Update achievable sums in reverse order to avoid overwriting
        for size in range(n - 1, 0, -1):
            for s in achievable_sums[size - 1]:
                achievable_sums[size].add(s + num)

    # Check for possible sizes from 1 to n-1
    for size in range(1, n):
        if total_sum * size % n == 0:  # Check if target sum is an integer
            target_sum = total_sum * size // n
            if target_sum in achievable_sums[size]:
                return True

    return False

