def maxIncreasingGroups(usageLimits: List[int]) -> int:
    # Sort the usage limits
    usageLimits.sort()

    n = len(usageLimits)

    def poss(groups: int) -> bool:
        sub = [usageLimits[0]]
        for i in range(1, groups):
            sub.append(max(0, sub[-1] - 1))

        for i in accumulate(sub):
            if i < 0:
                return False

        return True

    # Binary search for the maximum number of groups
    l, r = 0, n
    while l < r:
        mid = (l + r + 1) // 2
        if poss(mid):
            l = mid
        else:
            r = mid - 1

    return l

def countOfPairs(nums: List[int]) -> int:
    MOD = 1_000_000_007
    n = len(nums)

    # Initialize dp array
    dp = [[0] * 51 for _ in range(n + 1)]
    dp[n][0] = 1  # Base case: one way to form empty arrays

    # Loop through nums in reverse
    for i in range(n - 1, -1, -1):
        diff = 0
        for j in range(50, -1, -1):
            if j + 1 <= 50:
                dp[i][j] = dp[i + 1][j]  # Carry forward the previous value

            if j + diff <= nums[i]:
                dp[i][j] = (dp[i][j] + dp[i + 1][nums[i] - j - diff]) % MOD

            if j > 0:
                diff = max(0, nums[i] - j)

    return dp[0][0]

